'use client'

import * as React from 'react'
import { cn, radioGroupMachine } from "@/lib/utils"
import { CircleIcon } from 'lucide-react'

import { useMachine } from '../hooks/use-machine'

// Context
const RadioGroupContext = React.createContext<{
  state: any
  send: (event: any) => void
  disabled?: boolean
  required?: boolean
  name?: string
} | null>(null)

function useRadioGroup() {
  const context = React.useContext(RadioGroupContext)
  if (!context) {
    throw new Error('RadioGroupItem must be used within RadioGroup')
  }
  return context
}

const RadioGroup = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & {
    value?: string
    defaultValue?: string
    onValueChange?: (value: string) => void
    disabled?: boolean
    required?: boolean
    name?: string
  }
>(({ className, value, defaultValue, onValueChange, disabled, required, name, ...props }, ref) => {
  const [state, send] = useMachine(radioGroupMachine, {
    context: {
      value: value !== undefined ? value : defaultValue,
      disabled,
      required,
      name,
    },
  })

  // Sync controlled value
  React.useEffect(() => {
    if (value !== undefined && value !== state.context.value) {
      send({ type: 'VALUE.SET', value })
    }
  }, [value, send, state.context.value])

  const contextValue = React.useMemo(
    () => ({
      state,
      send: (evt: any) => {
        send(evt)
        if (evt.type === 'VALUE.SET') {
          onValueChange?.(evt.value)
        }
      },
      disabled,
      required,
      name,
    }),
    [state, send, disabled, required, name, onValueChange]
  )

  return (
    <RadioGroupContext.Provider value={contextValue}>
      <div role="radiogroup" className={cn('grid gap-2', className)} ref={ref} {...props} />
    </RadioGroupContext.Provider>
  )
})
RadioGroup.displayName = 'RadioGroup'

const RadioGroupItem = React.forwardRef<
  HTMLButtonElement,
  Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'value'> & { value: string }
>(({ className, value, disabled: itemDisabled, ...props }, ref) => {
  const { state, send, disabled: groupDisabled, required, name } = useRadioGroup()

  const isChecked = state.context.value === value
  const isDisabled = groupDisabled || itemDisabled

  return (
    <button
      type="button"
      role="radio"
      aria-checked={isChecked}
      data-state={isChecked ? 'checked' : 'unchecked'}
      disabled={isDisabled}
      aria-required={required}
      name={name}
      value={value}
      ref={ref}
      onClick={() => {
        if (!isDisabled) {
          send({ type: 'VALUE.SET', value })
        }
      }}
      className={cn(
        'aspect-square h-4 w-4 rounded-full border border-primary text-primary hover:shadow-sm focus:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50',
        className
      )}
      {...props}
    >
      <span data-slot="radio-indicator" className="flex items-center justify-center">
        {isChecked && (
          <CircleIcon className="h-2.5 w-2.5 fill-current text-current" strokeWidth={0} />
        )}
      </span>
    </button>
  )
})
RadioGroupItem.displayName = 'RadioGroupItem'

export { RadioGroup, RadioGroupItem }

import { inject, provide } from "vue";
import type { useRadioGroup } from "./use-radio-group";

export type UseRadioGroupReturn = ReturnType<typeof useRadioGroup>;

export const RadioGroupContextKey = Symbol("radioGroupContext");

export function provideRadioGroupContext(context: UseRadioGroupReturn) {
    provide(RadioGroupContextKey, context);
}

export function useRadioGroupContext() {
    const context = inject<UseRadioGroupReturn>(RadioGroupContextKey);
    if (!context) {
        throw new Error("useRadioGroupContext must be used within a RadioGroup component");
    }
    return context;
}

import { computed } from "vue";
import type { RadioGroupVueProps } from "@/lib/utils";
import { radioGroupConnect, radioGroupMachine } from "@/lib/utils";
import { normalizeProps, useMachine } from "@zag-js/vue";

type RadioGroupEmits = {
    (event: "update:modelValue", value: string | null): void;
    (event: "change", value: string | null): void;
};

export function useRadioGroup(props: RadioGroupVueProps, emit: RadioGroupEmits) {
    const machineProps = computed(() => ({
        id: props.id,
        value: props.modelValue ?? props.value,
        defaultValue:
            props.modelValue === undefined && props.value === undefined
                ? props.defaultValue
                : undefined,
        disabled: props.disabled,
        required: props.required,
        name: props.name,
        onValueChange(details: { value: string | null }) {
            emit("update:modelValue", details.value);
            emit("change", details.value);
        },
    }));

    const service = useMachine(radioGroupMachine, machineProps);
    const api = computed(() => radioGroupConnect(service, normalizeProps));

    return api;
}

import type { RadioGroupProps } from "@/lib/utils"

import { radioGroupVariants } from '../utils'

type PropDefinition = {
  type: StringConstructor | BooleanConstructor | null
  value?: string | boolean
}

type RadioGroupWeappProps = RadioGroupProps & {
  extClass?: string
}

const radioGroupProps = {
  value: { type: String, value: '' },
  defaultValue: { type: String, value: '' },
  name: { type: String, value: '' },
  form: { type: String, value: '' },
  disabled: { type: Boolean, value: false },
  invalid: { type: Boolean, value: false },
  required: { type: Boolean, value: false },
  readOnly: { type: Boolean, value: false },
  orientation: { type: String, value: 'vertical' },
  id: { type: String, value: '' },
  extClass: { type: String, value: '' },
} satisfies Partial<Record<keyof RadioGroupWeappProps, PropDefinition>>

Component({
  externalClasses: ['ext-class'],
  properties: radioGroupProps,
  relations: {
    '../radio-group-item/radio-group-item': {
      type: 'descendant',
      linked(target) {
        // Propagate value to child
        if (this.data.value) {
          target.setData({ checked: this.data.value === target.data.value })
        }
      },
    },
  },
  data: {
    className: '',
    value: '',
  },
  observers: {
    extClass: function (extClass) {
      this.setData({
        className: radioGroupVariants({ className: extClass }),
      })
    },
    value: function (val) {
      const nodes = this.getRelationNodes('../radio-group-item/radio-group-item')
      if (nodes && nodes.length) {
        nodes.forEach((node) => {
          node.setData({ checked: val === node.data.value })
        })
      }
      this.setData({ value: val })
      this.triggerEvent('change', { value: val })
    },
    defaultValue: function (val) {
      if (!this.data.value && val) {
        this.setData({ value: val })
      }
    },
  },
  methods: {
    handleChildChange(value) {
      this.setData({ value })
    },
  },
})

import type { RadioGroupItemWeappProps } from "@/lib/utils"
import { radioGroupItemVariants } from '../utils'

type RadioGroupItemProperty = {
    type: StringConstructor | BooleanConstructor
    value: string | boolean
}

type RadioGroupParent = {
    handleChildChange: (value: string) => void
}

const radioGroupItemProps = {
    value: { type: String, value: '' },
    disabled: { type: Boolean, value: false },
    invalid: { type: Boolean, value: false },
    extClass: { type: String, value: '' }
} satisfies Record<keyof RadioGroupItemWeappProps, RadioGroupItemProperty>

Component({
  options: {
    styleIsolation: "apply-shared",
  },
    externalClasses: ['ext-class'],
    properties: radioGroupItemProps,
    relations: {
        '../radio-group/radio-group': {
            type: 'ancestor',
        }
    },
    data: {
        checked: false,
        className: ''
    },
    observers: {
        'extClass': function (extClass: string) {
            // Note: We cannot easily toggle classes based on 'checked' inside observer if the variant doesn't support it directly without 'data-state'.
            // But we can manually toggle.
            // Shared variant: '... data-[state=checked]:bg-primary ...'
            // We will rely on template logic for the data-state attribute or conditional classes?
            // Since we are using standard `radioGroupItemVariants`, it expects `className`. 
            // It DOES NOT accept `checked` as a variant prop in the current definition (it uses data-attributes in React).
            // So we just generate the base class here.
            this.setData({
                className: radioGroupItemVariants({ className: extClass })
            })
        }
    },
    methods: {
        handleTap() {
            if (this.properties.disabled) return
            const parent = this.getRelationNodes('../radio-group/radio-group')[0] as RadioGroupParent | undefined
            if (parent) {
                parent.handleChildChange(this.properties.value)
            }
        }
    }
})
